INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Offline-USV nur für Serverräume relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Arbeitsplätze geeignet"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Offline-USV?', 3, '[{"text": "Absicherung bei Stromausfall", "correct": true, "because": "Kurzfristige Stromversorgung"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat eine Offline-USV?', 5, '[{"text": "Standby-Modus", "correct": true, "because": "Aktiviert bei Stromausfall"}, {"text": "Kostengünstig", "correct": true, "because": "Einfache Technologie"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Offline-USV schaltet bei Stromausfall um. b) Sie bietet Dauerschutz vor Spannungsschwankungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Schutz bei Schwankungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Offline-USV?', 4, '[{"text": "Batteriekapazität", "correct": false, "because": "Bestimmt Laufzeit"}, {"text": "Umschaltzeit", "correct": false, "because": "Kritisch für Geräte"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Offline-USV auch Spannung stabilisiert?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Standby, keine Regelung"}, {"text": "Ja", "correct": false, "because": "Nur bei höheren Modellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat eine Offline-USV?', 3, '[{"text": "Notstromversorgung", "correct": true, "because": "Überbrückt Stromausfall"}, {"text": "Datenbankgröße", "correct": false, "because": "Irrelevant"}, {"text": "Schnelle Datenübertragung", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Offline-USV?', 5, '[{"text": "Kosteneffizienz", "correct": true, "because": "Einfache Technologie"}, {"text": "Einfache Installation", "correct": true, "because": "Wenig Komplexität"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Offline-USV schützt bei Stromausfall. b) Sie ist für Server ungeeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für einfache Server geeignet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Offline-USV?', 4, '[{"text": "Batterie", "correct": false, "because": "Kern der Stromversorgung"}, {"text": "Umschaltmechanismus", "correct": false, "because": "Aktiviert Notstrom"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Offline-USV immer aktiv?', 2, '[{"text": "Nein", "correct": true, "because": "Nur im Standby-Modus"}, {"text": "Ja", "correct": false, "because": "Nur bei Ausfall aktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte schützt eine Offline-USV?', 4, '[{"text": "PCs", "correct": true, "because": "Einfache Arbeitsplätze"}, {"text": "Router", "correct": true, "because": "Netzwerkgeräte"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Offline-USV teuer ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kostengünstige Lösung"}, {"text": "Ja", "correct": false, "because": "Einfache Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Offline-USV?', 3, '[{"text": "Batterielaufzeit", "correct": true, "because": "Sichert Betriebszeit"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Sekundär"}, {"text": "Schriftgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Offline-USV bietet kurzfristigen Schutz. b) Sie regelt Spannungsschwankungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Spannungsregelung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen eine Offline-USV nützlich?', 5, '[{"text": "Schnelle Umschaltung", "correct": true, "because": "Minimiert Unterbrechungen"}, {"text": "Einfache Wartung", "correct": true, "because": "Wenig Komplexität"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Offline-USV unwichtig?', 3, '[{"text": "Kapazität", "correct": false, "because": "Bestimmt Laufzeit"}, {"text": "Anschlüsse", "correct": false, "because": "Sichert Geräte"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt eine Offline-USV vor langen Stromausfällen?', 3, '[{"text": "Nein", "correct": true, "because": "Nur kurzfristiger Schutz"}, {"text": "Ja", "correct": false, "because": "Begrenzte Laufzeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Offline-USV wartungsintensiv ist?', 2, '[{"text": "Nein", "correct": true, "because": "Einfache Technologie"}, {"text": "Ja", "correct": false, "because": "Wenig Wartung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal wähle ich für eine Offline-USV?', 4, '[{"text": "Standby-Funktion", "correct": true, "because": "Kern der Technologie"}, {"text": "Zufällige Daten", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Schutzfokus"}]');
